// verify-fixtures.mjs — assert the fixtures generated by `gen-fixtures.mjs`
// actually exercise what `docs/validation-plan.md` claims they do.
//
// A fixture that silently lacks a text layer is worse than no fixture: the
// manual walkthrough would "pass" while testing nothing. Run this after
// regenerating.
//
// Run: `node scripts/verify-fixtures.mjs`
import { readFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as pdfjs from 'pdfjs-dist/legacy/build/pdf.mjs';
import { PDFDocument, PDFName, PDFDict, PDFRawStream } from 'pdf-lib';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(ROOT, 'fixtures');

pdfjs.GlobalWorkerOptions.workerSrc = new URL(
  '../node_modules/pdfjs-dist/legacy/build/pdf.worker.mjs',
  import.meta.url
).href;

async function open(name) {
  const path = join(OUT, name);
  if (!existsSync(path)) throw new Error(`missing fixture: ${name} — run gen-fixtures.mjs first`);
  const bytes = new Uint8Array(readFileSync(path));
  const task = pdfjs.getDocument({
    // pdfjs detaches (transfers) the buffer it is handed, so it gets a copy —
    // otherwise the pdf-lib load below sees a zero-length array.
    data: new Uint8Array(bytes),
    isEvalSupported: false,
    useSystemFonts: false,
    // 0 = errors only. The subsetted CFF fonts we embed make pdfjs emit a
    // flood of glyph-program warnings that would drown out the report.
    verbosity: 0,
  });
  const doc = await task.promise;
  const pdf = await PDFDocument.load(bytes);
  return { doc, pdf, task, bytes, path };
}

async function close({ doc, task }) {
  try {
    await task.destroy();
  } catch {
    /* best effort */
  }
  void doc;
}

/** Concatenated text of one page, plus the count of text items. */
async function pageText(doc, pageNumber) {
  const page = await doc.getPage(pageNumber);
  const content = await page.getTextContent();
  const text = content.items.map((it) => ('str' in it ? it.str : '')).join('');
  return { text, items: content.items.length };
}

/**
 * Count image XObjects referenced by a page. `pdfjs.Ops` is no longer exported
 * from the v6 legacy build, so we walk the page resources through pdf-lib's
 * low-level context instead of pattern-matching raw bytes.
 */
function imageCount(pdf, pageIndex) {
  const resources = pdf.getPage(pageIndex).node.Resources();
  if (!resources) return 0;
  const xobjects = resources.lookupMaybe(PDFName.of('XObject'), PDFDict);
  if (!xobjects) return 0;
  let n = 0;
  for (const [, ref] of xobjects.entries()) {
    const stream = pdf.context.lookupMaybe(ref, PDFRawStream);
    if (stream && stream.dict.get(PDFName.of('Subtype')) === PDFName.of('Image')) {
      n += 1;
    }
  }
  return n;
}

const hasCjk = (s) => [...s].some((ch) => (ch.codePointAt(0) ?? 0) > 0x7e);
const hasLatin = (s) => /[A-Za-z]/.test(s);

const results = [];
function check(name, ok, detail) {
  results.push({ name, ok, detail });
}

async function main() {
  // ---- S1: pure Chinese, real text layer -------------------------------
  {
    const ctx = await open('s1-chinese.pdf');
    const { doc, pdf } = ctx;
    const { text, items } = await pageText(doc, 1);
    check('S1 页数 = 1', doc.numPages === 1, `实际 ${doc.numPages}`);
    check('S1 有文字层', items > 0, `${items} 个 text item`);
    check('S1 含中文', hasCjk(text), text.slice(0, 24));
    check('S1 含标点/数字行', text.includes('¥') && text.includes('0123456789'), '');
    await close(ctx);
  }

  // ---- S2: mixed CJK + Latin in one paragraph --------------------------
  {
    const ctx = await open('s2-mixed-color.pdf');
    const { doc, pdf } = ctx;
    const { text, items } = await pageText(doc, 1);
    check('S2 有文字层', items > 0, `${items} 个 text item`);
    check('S2 中英混排', hasCjk(text) && hasLatin(text), '');
    check('S2 含 ERROR/WARN 标记', text.includes('ERROR') && text.includes('WARN'), '');
    await close(ctx);
  }

  // ---- S3: 12 pages, image + vector rules ------------------------------
  {
    const ctx = await open('s3-multipage.pdf');
    const { doc, pdf } = ctx;
    check('S3 页数 = 12', doc.numPages === 12, `实际 ${doc.numPages}`);
    const { text } = await pageText(doc, 1);
    check('S3 有文字层', text.length > 50, `${text.length} 字符`);
    const imgs = imageCount(pdf, 0);
    check('S3 含栅格图片', imgs > 0, `${imgs} 个 image xobject`);
    const { text: last } = await pageText(doc, 12);
    check('S3 末页可读', last.includes('Page 12'), last.slice(0, 30));
    await close(ctx);
  }

  // ---- S4: AcroForm with four field kinds ------------------------------
  {
    const path = join(OUT, 's4-acroform.pdf');
    const pdf = await PDFDocument.load(readFileSync(path));
    const form = pdf.getForm();
    const fields = form.getFields();
    const kinds = fields.map((f) => f.constructor.name).sort();
    check('S4 字段数 = 4', fields.length === 4, `实际 ${fields.length}: ${kinds.join(', ')}`);
    check(
      'S4 四类字段齐备',
      kinds.join(',') === 'PDFCheckBox,PDFDropdown,PDFRadioGroup,PDFTextField',
      kinds.join(', ')
    );
    const names = fields.map((f) => f.getName()).sort().join(',');
    check('S4 字段名正确', names === 'city,full_name,plan,subscribe', names);
  }

  // ---- S5: scan-like, MUST have no text layer --------------------------
  {
    const ctx = await open('s5-scanned.pdf');
    const { doc, pdf } = ctx;
    check('S5 页数 = 2', doc.numPages === 2, `实际 ${doc.numPages}`);
    const { text, items } = await pageText(doc, 1);
    check('S5 无文字层(关键)', items === 0, `实际 ${items} 个 text item`);
    const imgs = imageCount(pdf, 0);
    check('S5 整页为图片', imgs > 0, `${imgs} 个 image xobject`);
    await close(ctx);
  }

  // ---- S6: 25 pages, > 5 MB --------------------------------------------
  {
    const ctx = await open('s6-large.pdf');
    const { doc, bytes } = ctx;
    check('S6 页数 = 25', doc.numPages === 25, `实际 ${doc.numPages}`);
    check('S6 体积 > 5 MB', bytes.byteLength > 5 * 1024 * 1024, `${(bytes.byteLength / 1024 / 1024).toFixed(2)} MB`);
    const { text } = await pageText(doc, 1);
    check('S6 有中文文字层', hasCjk(text), text.slice(0, 24));
    await close(ctx);
  }

  // ---- report ----------------------------------------------------------
  const pad = Math.max(...results.map((r) => r.name.length));
  for (const r of results) {
    console.log(`${r.ok ? '  ok  ' : ' FAIL '} ${r.name.padEnd(pad)}  ${r.detail}`);
  }
  const failed = results.filter((r) => !r.ok);
  console.log(`\n${results.length - failed.length}/${results.length} checks passed`);
  if (failed.length) process.exit(1);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
